import {clone,inspectComposite,proposeComposite,fingerprint,validateModel} from './composite-engine.mjs';
export function createSession(model){validateModel(model);return {model:clone(model),revision:1,checkedRevision:null,issues:[],candidates:[],reviewedRevision:null,events:[]};}
export function changeModel(state,model,reason){validateModel(model);if(!reason?.trim())throw new Error('변경 사유를 입력하세요.');state.model=clone(model);state.revision++;state.checkedRevision=null;state.reviewedRevision=null;state.candidates=[];state.issues=[];state.events.unshift({revision:state.revision,reason:reason.trim(),time:new Date().toISOString()});}
export function checkSession(state){state.issues=inspectComposite(state.model);state.checkedRevision=state.revision;return state.issues;}
export function proposeSession(state){checkSession(state);state.candidates=['movement','connection'].map(strategy=>({...proposeComposite(state.model,strategy),revision:state.revision}));return state.candidates;}
export function applyCandidate(state,candidate){if(!candidate?.ok||candidate.revision!==state.revision||candidate.source!==fingerprint(state.model))throw new Error('대안이 없거나 현재 개정과 다릅니다. 다시 생성하세요.');if(inspectComposite(candidate.model).length)throw new Error('대안의 필수 조건 재검사 실패');for(const o of state.model.objects.filter(o=>o.locked||o.hold)){const next=candidate.model.objects.find(n=>n.id===o.id);if(JSON.stringify(next)!==JSON.stringify(o))throw new Error('고정·Hold 객체 변경 불가');}changeModel(state,candidate.model,`${candidate.strategy==='movement'?'이동 최소':'연결거리 우선'} 대안 적용`);checkSession(state);}
export function reviewSession(state){if(state.checkedRevision!==state.revision||state.issues.length)throw new Error('현재 개정의 필수 조건 검사를 통과해야 합니다.');state.reviewedRevision=state.revision;state.events.unshift({revision:state.revision,reason:'샘플 검토 완료 (실제 설계 승인 아님)',time:new Date().toISOString()});}
export function reportSession(state){return {scope:'2.5D 직교 박스 예시 검토. DWG 파싱·실배관 라우팅·설계 승인 기능 없음.',revision:state.revision,checkedRevision:state.checkedRevision,reviewedRevision:state.reviewedRevision,issues:state.checkedRevision===state.revision?clone(state.issues):null,model:clone(state.model),events:clone(state.events)};}
